/** Block size of the compression function, in bytes. */
export const BLOCK_SIZE = 64;

/** Length of a SHA-256 digest, in bytes. */
export const DIGEST_SIZE = 32;

function rotr(x, n) {
  return (x >>> n) | (x << (32 - n));
}

/**
 * Compute the SHA-256 digest of a byte array.
 *
 * @param {Uint8Array} message
 * @returns {Uint8Array} 32 raw digest bytes
 */
export function sha256(message) {
  const bitLength = message.length * 8;

  // Pad with 0x80, then zeros, so the total is 56 mod 64, then a 64-bit
  // big-endian bit count.
  const padded = new Uint8Array((((message.length + 8) >> 6) + 1) << 6);
