  padded[lenOffset] = (high >>> 24) & 0xff;
  padded[lenOffset + 1] = (high >>> 16) & 0xff;
  padded[lenOffset + 2] = (high >>> 8) & 0xff;
  padded[lenOffset + 3] = high & 0xff;
  padded[lenOffset + 4] = (low >>> 24) & 0xff;
  padded[lenOffset + 5] = (low >>> 16) & 0xff;
  padded[lenOffset + 6] = (low >>> 8) & 0xff;
  padded[lenOffset + 7] = low & 0xff;

  const h = INITIAL_STATE.slice();
  const w = new Uint32Array(64);

  for (let offset = 0; offset < padded.length; offset += BLOCK_SIZE) {
    for (let t = 0; t < 16; t++) {
      const i = offset + t * 4;
      w[t] = ((padded[i] << 24) | (padded[i + 1] << 16) | (padded[i + 2] << 8) | padded[i + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }

    let [a, b, c, d, e, f, g, hh] = h;

    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (hh + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;

      hh = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
