/**
 * HMAC (RFC 2104), parameterised over any hash descriptor exposing
 * `{ blockSize, digestSize, hash }`.
 */

import { concatBytes } from '../encoding/bytes.mjs';

/**
 * Compute HMAC(key, message) for the given hash.
 *
 * @param {{blockSize: number, digestSize: number, hash: (b: Uint8Array) => Uint8Array}} algorithm
 * @param {Uint8Array} key
 * @param {Uint8Array} message
 * @returns {Uint8Array} raw MAC bytes
 */
export function hmac(algorithm, key, message) {
  const { blockSize, hash } = algorithm;

  // Keys longer than a block are hashed down; shorter keys are zero padded.
  let block = new Uint8Array(blockSize);
  if (key.length > blockSize) {
    block.set(hash(key));
  } else {
    block.set(key);
  }

  const ipad = new Uint8Array(blockSize);
  const opad = new Uint8Array(blockSize);
  for (let i = 0; i < blockSize; i++) {
    ipad[i] = block[i] ^ 0x36;
    opad[i] = block[i] ^ 0x5c;
  }

  const inner = hash(concatBytes(ipad, message));
  return hash(concatBytes(opad, inner));
}

