/**
 * Value wrappers that let JavaScript carry the parts of Python's type system
 * this port cares about.
 *
 * JavaScript has a single `number`, so a JSON literal like `1.0` would be
 * indistinguishable from `1` after parsing — yet Python renders them as `1.0`
 * and `1`.  Non-integral (or explicitly float-formatted) literals are therefore
 * wrapped in `PyFloat`, while integers stay as `number`/`bigint`.
 */

/** Marks a value that must render like a Python `float`. */
export class PyFloat {
  /** @param {number} value */
  constructor(value) {
    this.value = value;
  }

  valueOf() {
    return this.value;
  }
}

/**
 * Python dicts preserve insertion order for keys of every type, whereas plain
 * JS objects reorder integer-like keys.  `Map` matches Python, so decoded JSON
 * objects are represented as `Map`s.
 *
 * @param {Iterable<[unknown, unknown]>} [entries]
 * @returns {Map<unknown, unknown>}
 */
export function pyDict(entries = []) {
  return new Map(entries);
}

/**
 * True when `value` should be rendered as a Python integer.
 *
 * @param {unknown} value
 * @returns {boolean}
 */
export function isPyInt(value) {
  return typeof value === 'bigint' || (typeof value === 'number' && Number.isInteger(value));
}

/**
 * Unwrap a numeric value (`number`, `bigint` or `PyFloat`) to a JS number.
 *
 * @param {unknown} value
 * @returns {number}
 */
export function toJsNumber(value) {
  if (value instanceof PyFloat) return value.value;
  if (typeof value === 'bigint') return Number(value);
  return Number(value);
}

