/**
 * Python's `repr()` for the value shapes this program prints.
 *
 * `print(dict)` goes through `repr`, so reproducing the CPython rules exactly is
 * what makes `{'info': 'a\tb', 'iat': 1}` come out character for character.
 */

import { PyFloat, isPyInt } from './types.mjs';

// `str.isprintable()`: everything in the Unicode "Other" (C*) and "Separator"
// (Z*) categories is unprintable, except the ASCII space.
const UNPRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintableChar(ch) {
  return ch === ' ' || !UNPRINTABLE.test(ch);
}

function hexEscape(codePoint) {
  if (codePoint <= 0xff) return '\\x' + codePoint.toString(16).padStart(2, '0');
  if (codePoint <= 0xffff) return '\\u' + codePoint.toString(16).padStart(4, '0');
  return '\\U' + codePoint.toString(16).padStart(8, '0');
}

/**
 * Render a string the way CPython's `repr()` does.
 *
 * Single quotes are preferred; a string that contains `'` but no `"` is wrapped
 * in double quotes instead.  Only the active quote character is escaped.
 *
 * @param {string} str
 * @returns {string}
 */
export function reprString(str) {
  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of str) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (isPrintableChar(ch)) {
      out += ch;
    } else {
      out += hexEscape(ch.codePointAt(0));
    }
  }
  return out + quote;
}

/**
 * Render a float the way CPython's `repr()` does: shortest round-tripping form,
 * always with a decimal point or exponent, switching to scientific notation
 * below 1e-4 and at or above 1e16.
 *
 * @param {number} value
 * @returns {string}
 */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const sign = value < 0 || Object.is(value, -0) ? '-' : '';
  const abs = Math.abs(value);
  if (abs === 0) return sign + '0.0';

  const exponent = Math.floor(Math.log10(abs));
  if (exponent < -4 || exponent >= 16) {
    // Let the engine pick the shortest significand, then reformat the exponent
    // with Python's mandatory sign and two-digit minimum.
    const [mantissa, exp] = abs.toExponential().split('e');
    const shortest = String(abs);
    let digits = mantissa;
    if (!shortest.includes('e')) {
      // `String()` was more compact; recover its significant digits.
      const compact = shortest.replace(/[-.]/g, '').replace(/^0+/, '').replace(/0+$/, '') || '0';
      digits = compact.length > 1 ? compact[0] + '.' + compact.slice(1) : compact;
    }
    const expNum = Number(exp);
    const expSign = expNum < 0 ? '-' : '+';
    return sign + digits + 'e' + expSign + String(Math.abs(expNum)).padStart(2, '0');
  }

  let text = String(abs);
  if (text.includes('e')) {
    // e.g. 1e-5 handled above; anything left is safe to expand.
    text = abs.toFixed(Math.max(0, 17 - exponent));
    text = text.replace(/0+$/, '');
    if (text.endsWith('.')) text += '0';
  }
  if (!text.includes('.')) text += '.0';
  return sign + text;
}

/**
 * Render any supported value the way CPython's `repr()` does.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function repr(value) {
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'string') return reprString(value);
  if (value instanceof PyFloat) return reprFloat(value.value);
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return isPyInt(value) ? String(value) : reprFloat(value);

  if (value instanceof Map) {
    const parts = [];
    for (const [k, v] of value) parts.push(repr(k) + ': ' + repr(v));
    return '{' + parts.join(', ') + '}';
  }
  if (Array.isArray(value)) {
    return '[' + value.map(repr).join(', ') + ']';
  }

  const parts = [];
  for (const [k, v] of Object.entries(value)) parts.push(repr(k) + ': ' + repr(v));
  return '{' + parts.join(', ') + '}';
}

