/**
 * Python-compatible JSON encode/decode.
 *
 * `dumps` reproduces CPython's `ensure_ascii=True` output and accepts the
 * compact `separators=(',', ':')` form that JOSE libraries use for both the
 * header and the claim set.  Byte-for-byte agreement matters here: the encoded
 * segments are what gets signed, so a single differing escape changes the token.
 */

import { PyFloat, isPyInt } from './types.mjs';
import { reprFloat } from './repr.mjs';

const SHORT_ESCAPES = {
  '\\': '\\\\',
  '"': '\\"',
  '\b': '\\b',
  '\f': '\\f',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
};

/**
 * Escape a string exactly like CPython's `encode_basestring_ascii`: everything
 * outside printable ASCII (0x20-0x7e) becomes a `\uXXXX` escape, with astral
 * code points emitted as a surrogate pair.
 *
 * @param {string} str
 * @returns {string}
 */
export function encodeStringAscii(str) {
  let out = '"';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const code = str.charCodeAt(i);
    if (SHORT_ESCAPES[ch] !== undefined) {
      out += SHORT_ESCAPES[ch];
    } else if (code >= 0x20 && code <= 0x7e) {
      out += ch;
    } else {
