    this.isHelp = Boolean(options.isHelp);
    this.default = options.default === undefined ? null : options.default;
    this.metavar =
      options.metavar ||
      (this.choices ? `{${this.choices.join(',')}}` : String(this.dest).toUpperCase());
  }

  /** Name used in error messages, e.g. `--verify_iat`. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** Rendering used in the usage line and the options listing. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return `${this.optionStrings.join(', ')} ${this.metavar}`;
  }

  formatUsagePart() {
    const body = this.nargs === 0 ? this.optionStrings[0] : `${this.optionStrings[0]} ${this.metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean, stdout?: (s: string) => void, stderr?: (s: string) => void}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog || 'program';
    this.actions = [];
    this.optionStringActions = new Map();
    this.stdout = options.stdout || ((text) => process.stdout.write(text));
    this.stderr = options.stderr || ((text) => process.stderr.write(text));

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        isHelp: true,
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * Register an option. Mirrors `parser.add_argument('--data', type=str, ...)`.
   *
   * @param {string|string[]} flags
   * @param {object} [options]
   * @returns {Action}
   */
  addArgument(flags, options = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    const dest =
      options.dest ||
      (optionStrings.find((flag) => flag.startsWith('--')) || optionStrings[0])
        .replace(/^-+/, '')
        .replace(/-/g, '_');

    const action = new Action(optionStrings, { ...options, dest });
    this.actions.push(action);
    for (const flag of optionStrings) this.optionStringActions.set(flag, action);
    return action;
  }

  /** `usage: prog [-h] --data DATA --verify_iat {true,false}` */
  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsagePart());
    return `usage: ${this.prog}${parts.length ? ' ' + parts.join(' ') : ''}\n`;
  }

  /** Full `--help` output. */
  formatHelp() {
    // argparse aligns help text at `min(max_action_length + 2, 24)`.
    const maxInvocation = this.actions.reduce(
      (max, action) => Math.max(max, action.formatInvocation().length + 2),
      0,
    );
    const helpPosition = Math.min(maxInvocation + 2, 24);

    let out = this.formatUsage();
    out += '\noptions:\n';
    for (const action of this.actions) {
      const invocation = '  ' + action.formatInvocation();
      if (!action.help) {
        out += invocation + '\n';
      } else if (invocation.length < helpPosition) {
        out += invocation + ' '.repeat(helpPosition - invocation.length) + action.help + '\n';
      } else {
        out += invocation + '\n' + ' '.repeat(helpPosition) + action.help + '\n';
      }
    }
    return out;
  }

  /** Print usage + message to stderr and exit with status 2. */
  error(message) {
    this.stderr(this.formatUsage());
    this.stderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Resolve an `-x`/`--xyz` token to an action, honouring `=` and unambiguous
   * prefix abbreviation.
   *
   * @returns {{action: Action|null, explicitArg: string|null}|null}
   *   `null` means the token is not an option at all.
   */
  #parseOptional(argString) {
    if (!argString || argString[0] !== '-') return null;
    if (argString === '-') return null;

    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), explicitArg: null };
    }

    let head = argString;
    let explicitArg = null;
    const eq = argString.indexOf('=');
    if (eq >= 0) {
      head = argString.slice(0, eq);
      explicitArg = argString.slice(eq + 1);
      if (this.optionStringActions.has(head)) {
        return { action: this.optionStringActions.get(head), explicitArg };
      }
    }

    const matches = [];
    for (const [flag, action] of this.optionStringActions) {
      if (flag.startsWith(head)) matches.push({ flag, action });
    }
    if (matches.length === 1) {
      return { action: matches[0].action, explicitArg };
    }
    if (matches.length > 1) {
      const flags = matches.map((match) => match.flag).join(', ');
      this.error(`ambiguous option: ${argString} could match ${flags}`);
    }

    // A bare negative number is a value, not an option, as long as no option
    // itself looks like a negative number.
    if (NEGATIVE_NUMBER.test(argString) && !this.#hasNegativeNumberOptions()) return null;
    if (argString.includes(' ')) return null;

    return { action: null, explicitArg: null };
  }

  #hasNegativeNumberOptions() {
    for (const flag of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER.test(flag)) return true;
    }
    return false;
  }

  #checkValue(action, value) {
    if (action.choices && !action.choices.includes(value)) {
      const choices = action.choices.map((choice) => `'${choice}'`).join(', ');
      this.error(`argument ${action.name}: invalid choice: '${value}' (choose from ${choices})`);
    }
    return value;
  }

  /**
   * Parse an argv slice (without the interpreter/script entries).
   *
   * @param {string[]} argv
   * @returns {Record<string, unknown>} namespace of `dest -> value`
   */
  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = action.default;
    }

    const seen = new Set();
    const extras = [];
    let positionalOnly = false;

    for (let i = 0; i < argv.length; i++) {
      const arg = argv[i];

      if (positionalOnly) {
        extras.push(arg);
        continue;
      }
      if (arg === '--') {
        positionalOnly = true;
        continue;
      }

      const optional = this.#parseOptional(arg);
      if (optional === null) {
        extras.push(arg);
        continue;
      }
      if (optional.action === null) {
        extras.push(arg);
        continue;
      }

      const { action, explicitArg } = optional;

      if (action.isHelp) {
        this.stdout(this.formatHelp());
        throw new SystemExit(0);
      }

      if (action.nargs === 0) {
        if (explicitArg !== null) {
          this.error(`argument ${action.name}: ignored explicit argument '${explicitArg}'`);
        }
        namespace[action.dest] = true;
        seen.add(action);
        continue;
      }

      let raw = explicitArg;
      if (raw === null) {
        const next = i + 1 < argv.length ? argv[i + 1] : undefined;
        const nextIsValue =
          next !== undefined && next !== '--' && this.#parseOptional(next) === null;
        if (!nextIsValue) {
          this.error(`argument ${action.name}: expected one argument`);
        }
        raw = next;
        i++;
      }

      namespace[action.dest] = action.type(this.#checkValue(action, raw));
      seen.add(action);
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length) {
      const names = missing.map((action) => action.optionStrings.join('/')).join(', ');
      this.error(`the following arguments are required: ${names}`);
    }

    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

