/**
 * Signing algorithms, keyed by their JWA `alg` name.
 *
 * Only the HMAC family backed by SHA-256 is implemented, which is what
 * `jwt.encode(payload, secret)` defaults to.  Anything else raises the same
 * error python-jose raises for an unsupported algorithm.
 */

import { SHA256 } from '../hash/sha256.mjs';
import { hmac } from '../hash/hmac.mjs';
import { utf8Encode, bytesEqual } from '../encoding/bytes.mjs';
import { JWSAlgorithmError, JWKError } from './errors.mjs';

export const ALGORITHMS = {
  HS256: 'HS256',
  NONE: 'none',
};

/** Symmetric key wrapper, the analogue of python-jose's `HMACKey`. */
export class HMACKey {
  /**
   * @param {string|Uint8Array} key
   * @param {string} algorithm
   */
  constructor(key, algorithm) {
    if (algorithm !== ALGORITHMS.HS256) {
      throw new JWSAlgorithmError(`${algorithm} is not a valid hash algorithm`);
    }
    if (typeof key === 'string') {
      this.key = utf8Encode(key);
    } else if (key instanceof Uint8Array) {
      this.key = key;
    } else {
      throw new JWKError('Expected a string or bytes key');
    }
    this.hashAlgorithm = SHA256;
  }

  /**
   * @param {Uint8Array} message
   * @returns {Uint8Array} raw MAC bytes
   */
  sign(message) {
    return hmac(this.hashAlgorithm, this.key, message);
  }

  /**
   * @param {Uint8Array} message
   * @param {Uint8Array} signature
   * @returns {boolean}
   */
  verify(message, signature) {
    return bytesEqual(this.sign(message), signature);
  }
}

/**
 * Build a key object for `algorithm`.
 *
 * @param {string|Uint8Array|HMACKey} key
 * @param {string} algorithm
 * @returns {HMACKey}
 */
export function getKey(key, algorithm) {
  if (key instanceof HMACKey) return key;
  return new HMACKey(key, algorithm);
}

