/**
 * JWS compact serialization — `jose.jws`.
 */

import { base64urlEncode, base64urlDecode } from '../encoding/base64url.mjs';
import { utf8Encode, utf8Decode, concatBytes } from '../encoding/bytes.mjs';
import { dumps, loads } from '../python/json.mjs';
import { ALGORITHMS, getKey } from './algorithms.mjs';
import { JWSError, JWSSignatureError, JWSAlgorithmError } from './errors.mjs';

const COMPACT = { separators: [',', ':'] };

/**
 * Encode the protected header.  python-jose sorts the header keys, which is why
 * `alg` precedes `typ` in every token it produces.
 *
 * @param {string} algorithm
 * @param {Map<string, unknown>|Record<string, unknown>|null} [additionalHeaders]
 * @returns {string} base64url segment
 */
function encodeHeader(algorithm, additionalHeaders) {
  const header = new Map([
    ['typ', 'JWT'],
    ['alg', algorithm],
  ]);
  if (additionalHeaders) {
    const entries =
      additionalHeaders instanceof Map
        ? additionalHeaders.entries()
        : Object.entries(additionalHeaders);
    for (const [key, value] of entries) header.set(key, value);
  }
  const json = dumps(header, { ...COMPACT, sortKeys: true });
  return base64urlEncode(utf8Encode(json));
}

/**
 * @param {Uint8Array|string} payload
 * @returns {string} base64url segment
 */
function encodePayload(payload) {
  const bytes = typeof payload === 'string' ? utf8Encode(payload) : payload;
  return base64urlEncode(bytes);
}

/**
 * Produce a compact JWS.
 *
 * @param {Uint8Array|string} payload raw payload bytes
 * @param {string|Uint8Array} key
 * @param {{headers?: object|Map<string, unknown>, algorithm?: string}} [options]
 * @returns {string}
 */
export function sign(payload, key, options = {}) {
  const algorithm = options.algorithm || ALGORITHMS.HS256;
  if (algorithm !== ALGORITHMS.HS256) {
    throw new JWSAlgorithmError(`Algorithm ${algorithm} not supported.`);
  }

  const signingInput = `${encodeHeader(algorithm, options.headers)}.${encodePayload(payload)}`;
  const signature = getKey(key, algorithm).sign(utf8Encode(signingInput));
  return `${signingInput}.${base64urlEncode(signature)}`;
}

/**
 * Split a compact token into its three segments.
 *
 * @param {string} token
 * @returns {{header: Map<string, unknown>, payload: Uint8Array, signature: Uint8Array, signingInput: Uint8Array}}
 */
export function loadToken(token) {
  const text = token instanceof Uint8Array ? utf8Decode(token) : String(token);
  const parts = text.split('.');
  if (parts.length !== 3) {
    throw new JWSError('Not enough segments');
  }

  const [headerSegment, payloadSegment, signatureSegment] = parts;

  let header;
  try {
    header = loads(utf8Decode(base64urlDecode(headerSegment)));
  } catch (error) {
    throw new JWSError('Invalid header string: ' + error.message);
  }
  if (!(header instanceof Map)) {
    throw new JWSError('Invalid header string: must be a json object');
  }

  let payload;
  let signature;
  try {
    payload = base64urlDecode(payloadSegment);
  } catch (error) {
    throw new JWSError('Invalid payload padding: ' + error.message);
  }
  try {
    signature = base64urlDecode(signatureSegment);
  } catch (error) {
    throw new JWSError('Invalid crypto padding: ' + error.message);
  }

  return {
    header,
    payload,
    signature,
    signingInput: utf8Encode(`${headerSegment}.${payloadSegment}`),
  };
}

/**
 * Verify a compact JWS and return its raw payload bytes.
 *
 * @param {string} token
 * @param {string|Uint8Array} key
 * @param {string[]|string} algorithms permitted `alg` values
 * @param {boolean} [verify=true] when false, skip signature verification
 * @returns {Uint8Array}
 */
export function verify(token, key, algorithms, verify_ = true) {
  const { header, payload, signature, signingInput } = loadToken(token);
  if (!verify_) return payload;

  const allowed = algorithms === null || algorithms === undefined
    ? null
    : Array.isArray(algorithms)
      ? algorithms
      : [algorithms];

  const alg = header.get('alg');
  if (!alg) {
    throw new JWSAlgorithmError('No algorithm was specified in the JWS header.');
  }
  if (allowed !== null && !allowed.includes(alg)) {
    throw new JWSAlgorithmError('The specified alg value is not allowed');
  }

  if (!getKey(key, alg).verify(signingInput, signature)) {
    throw new JWSSignatureError('Signature verification failed.');
  }
  return payload;
}

/**
 * Read the protected header without verifying the signature.
 *
 * @param {string} token
 * @returns {Map<string, unknown>}
 */
export function getUnverifiedHeader(token) {
  return loadToken(token).header;
}

