/**
 * JWT encode/decode — `jose.jwt`.
 *
 * The claim-validation switches follow python-jose's `options` dict, so
 * `options={'verify_iat': False}` skips exactly the `iat` check and leaves every
 * other default (`verify_signature`, `verify_exp`, ...) enabled.
 */

import { utf8Encode, utf8Decode } from '../encoding/bytes.mjs';
import { dumps, loads } from '../python/json.mjs';
import { toJsNumber, PyFloat } from '../python/types.mjs';
import { ALGORITHMS } from './algorithms.mjs';
import * as jws from './jws.mjs';
import { JWTError, JWTClaimsError, ExpiredSignatureError } from './errors.mjs';

const COMPACT = { separators: [',', ':'] };

/** python-jose's default `options` for `decode`. */
export const DEFAULT_OPTIONS = {
  verify_signature: true,
  verify_aud: true,
  verify_iat: true,
  verify_exp: true,
  verify_nbf: true,
  verify_iss: true,
  verify_sub: true,
  verify_jti: true,
  verify_at_hash: true,
  require_aud: false,
  require_iat: false,
  require_exp: false,
  require_nbf: false,
  require_iss: false,
  require_sub: false,
  require_jti: false,
  require_at_hash: false,
  leeway: 0,
};

/**
 * Encode a claim set into a signed JWT.
 *
 * The claims are serialized with compact separators and `ensure_ascii`, in
 * insertion order — the header is the only part whose keys get sorted.
 *
 * @param {Map<string, unknown>|Record<string, unknown>} claims
 * @param {string|Uint8Array} key
 * @param {{algorithm?: string, headers?: object|Map<string, unknown>}} [options]
 * @returns {string}
 */
export function encode(claims, key, options = {}) {
  const algorithm = options.algorithm || ALGORITHMS.HS256;
  const payload = utf8Encode(dumps(claims, COMPACT));
  return jws.sign(payload, key, { algorithm, headers: options.headers });
}

/** Current time in whole seconds, matching Python's `time.time()` floor. */
function now() {
  return Math.floor(Date.now() / 1000);
}

function asTimestamp(value) {
  if (typeof value === 'bigint') return Number(value);
  if (value instanceof PyFloat) return value.value;
  if (typeof value === 'number') return value;
  if (typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))) {
    return Number(value);
  }
  return NaN;
}

function validateIat(claims) {
  if (!claims.has('iat')) return;
  if (!Number.isFinite(asTimestamp(claims.get('iat')))) {
    throw new JWTClaimsError('Issued At claim (iat) must be an integer.');
  }
}

function validateNbf(claims, leeway) {
  if (!claims.has('nbf')) return;
  const nbf = asTimestamp(claims.get('nbf'));
  if (!Number.isFinite(nbf)) {
