/**
 * Port of `test17.py`.
 *
 *   iat (issued at) records the token's issue time; `--verify_iat` decides
 *   whether decoding validates that claim.
 */

import { ArgumentParser, SystemExit } from './lib/python/argparse.mjs';
import { jwt } from './lib/jose/index.mjs';
import { repr } from './lib/python/repr.mjs';

// argparse derives `prog` from the executable name; keep it aligned with the
// reference binary so usage/error text matches byte for byte.
const PROG = 'test17_executable';

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--data', { type: String, required: true });
  parser.addArgument('--verify_iat', {
    type: String,
    required: true,
    choices: ['true', 'false'],
  });
  return parser;
}

function main(argv) {
  const args = buildParser().parseArgs(argv);

  const secret = 'secret';
  const payload = new Map([
    ['info', args.data],
    ['iat', Math.floor(Date.now() / 1000)],
  ]);
  const token = jwt.encode(payload, secret);
  console.log(token);

  const verifyIat = args.verify_iat === 'true';
  const options = { verify_iat: verifyIat };
  const decoded = jwt.decode(token, secret, { options, algorithms: ['HS256'] });
  console.log(repr(decoded));
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    process.exitCode = error.code;
  } else {
    // Match CPython: uncaught exceptions print a traceback header and exit 1.
    process.stderr.write(`Traceback (most recent call last):\n${error.name}: ${error.message}\n`);
    process.exitCode = 1;
  }
}

