/**
 * Differential test: runs the reference executable and the port on identical
 * argv, then compares stdout/stderr/exit status.
 *
 * Tokens embed `iat`, so a literal diff would fail whenever the clock ticks.
 * Instead each run's token is (a) normalized by substituting its own iat, and
 * (b) cross-checked: the reference token's signature is recomputed with this
 * port's HMAC over the reference's own header.payload, which proves the signing
 * path is bit-identical without needing the two runs to share a timestamp.
 */

import { execFileSync } from 'node:child_process';
import { utf8Encode, utf8Decode } from '../output/lib/encoding/bytes.mjs';
import { base64urlEncode, base64urlDecode } from '../output/lib/encoding/base64url.mjs';
import { HMACKey } from '../output/lib/jose/algorithms.mjs';

const REFERENCE = '/workspace/dataset/test17_executable';
const PORT = ['/output/test17.mjs'];

function run(command, args, argv) {
  try {
    const stdout = execFileSync(command, [...args, ...argv], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout, stderr: '' };
  } catch (error) {
    return {
      code: error.status === null ? -1 : error.status,
      stdout: error.stdout === undefined ? '' : error.stdout,
      stderr: error.stderr === undefined ? '' : error.stderr,
    };
  }
}

/** Replace the concrete iat/token with placeholders so runs are comparable. */
function normalize(text) {
  const tokenMatch = text.match(/^([\w-]+)\.([\w-]+)\.([\w-]+)$/m);
  if (!tokenMatch) return { text, token: null };
  const iat = JSON.parse(utf8Decode(base64urlDecode(tokenMatch[2]))).iat;
  const stamped = new RegExp(String(iat), 'g');
  const canonicalToken = tokenMatch[0].replace(
    tokenMatch[2],
    base64urlEncode(utf8Encode(utf8Decode(base64urlDecode(tokenMatch[2])).replace(String(iat), '<IAT>'))),
  );
  return {
    text: text.replace(tokenMatch[0], canonicalToken).replace(stamped, '<IAT>'),
    token: tokenMatch[0],
  };
}

/** Re-sign the reference token's own signing input with our HMAC. */
function crossCheckSignature(token) {
  const [header, payload, signature] = token.split('.');
  const key = new HMACKey('secret', 'HS256');
  const ours = base64urlEncode(key.sign(utf8Encode(`${header}.${payload}`)));
  return ours === signature;
}

const CASES = [
  ['--data', 'iat_data_5', '--verify_iat', 'false'],
  ['--data', 'iat_data_8', '--verify_iat', 'false'],
  ['--data', 'iat_data_1', '--verify_iat', 'true'],
  ['--data', 'iat_data_19', '--verify_iat', 'true'],
  ['--data', '', '--verify_iat', 'true'],
  ['--data', 'a', '--verify_iat', 'false'],
  ['--data', "a'b", '--verify_iat', 'true'],
  ['--data', 'he said "hi"', '--verify_iat', 'true'],
  ['--data', 'both \' and "', '--verify_iat', 'true'],
  ['--data', '中文测试', '--verify_iat', 'false'],
  ['--data', 'emoji \u{1F600}\u{1F680}', '--verify_iat', 'true'],
  ['--data', 'tab\tnl\ncr\rbs\\', '--verify_iat', 'true'],
  ['--data', 'é ­', '--verify_iat', 'true'],
  ['--data', 'space  and  more', '--verify_iat', 'false'],
  ['--data', '-5', '--verify_iat', 'true'],
  ['--data', '--weird', '--verify_iat', 'true'],
  ['--data', 'x'.repeat(500), '--verify_iat', 'true'],
  ['--data=eqtest', '--verify_iat=true'],
  ['--dat', 'abbrev', '--verify', 'false'],
  ['--data', 'a', '--data', 'b', '--verify_iat', 'true'],
  ['--verify_iat', 'true', '--data', 'reordered'],
  ['--help'],
  ['-h'],
  ['--data', 'a', '-h'],
  [],
  ['--data', 'x'],
  ['--verify_iat', 'true'],
  ['--data', 'x', '--verify_iat', 'maybe'],
  ['--data', 'x', '--verify_iat', 'TRUE'],
  ['--data', 'a', '--verify_iat', 'true', 'extra'],
  ['--xyz', '1', '--data', 'a', '--verify_iat', 'true'],
  ['--xyz', '1'],
  ['--data', '--', '--verify_iat', 'true'],
  ['--verify_iat', 'true', '--data'],
  ['-data', 'a', '--verify_iat', 'true'],
  ['--d', 'a', '--verify_iat', 'true'],
];

let failures = 0;
for (const argv of CASES) {
  const expected = run(REFERENCE, [], argv);
  const actual = run('node', PORT, argv);

  const expectedNorm = normalize(expected.stdout);
  const actualNorm = normalize(actual.stdout);

  const problems = [];
  if (expected.code !== actual.code) problems.push(`exit ${expected.code} != ${actual.code}`);
  if (expectedNorm.text !== actualNorm.text) problems.push('stdout differs');
  if (expected.stderr !== actual.stderr) problems.push('stderr differs');
  if (expectedNorm.token && !crossCheckSignature(expectedNorm.token)) {
    problems.push('signature mismatch vs reference token');
  }

  const label = JSON.stringify(argv);
  if (problems.length) {
    failures++;
    console.log(`FAIL ${label}\n  ${problems.join('; ')}`);
    console.log(`  expected stdout: ${JSON.stringify(expectedNorm.text)}`);
    console.log(`  actual   stdout: ${JSON.stringify(actualNorm.text)}`);
    console.log(`  expected stderr: ${JSON.stringify(expected.stderr)}`);
    console.log(`  actual   stderr: ${JSON.stringify(actual.stderr)}`);
  } else {
    console.log(`ok   ${label}`);
  }
}

console.log(`\n${CASES.length - failures}/${CASES.length} cases matched`);
if (failures) process.exitCode = 1;

