// Fuzz: random strings drawn from ASCII, control, Latin-1, BMP and astral
// ranges, which is where JSON `ensure_ascii` escaping and Python `repr`
// printability rules are most likely to diverge.
function randomChar(random) {
  const bucket = Math.floor(random() * 6);
  if (bucket === 0) return String.fromCharCode(32 + Math.floor(random() * 95));
  if (bucket === 1) return String.fromCharCode(Math.floor(random() * 32));
  if (bucket === 2) return String.fromCharCode(0x7f + Math.floor(random() * 0x81));
  if (bucket === 3) return String.fromCharCode(0x100 + Math.floor(random() * 0x2f00));
  if (bucket === 4) return String.fromCodePoint(0x10000 + Math.floor(random() * 0x1000));
  return ['\'', '"', '\\', '\t', '\n', '\r', ' ', '­', ' '][Math.floor(random() * 9)];
}

let seed = 20260810;
const random = () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};

for (let i = 0; i < 40; i++) {
  const length = 1 + Math.floor(random() * 12);
