/**
 * Reproduce the four sample tokens recorded in the task description, whose iat
 * is 1773060987. This checks the encode path against ground truth without
 * depending on the current clock.
 */

import { jwt } from '../output/lib/jose/index.mjs';
import { repr } from '../output/lib/python/repr.mjs';

const EXPECTED = [
  ['iat_data_5', 'false', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpbmZvIjoiaWF0X2RhdGFfNSIsImlhdCI6MTc3MzA2MDk4N30.y_GRDJRcCz_XHItuYzZrxN_Sblm171V3r898LWLYHZ4', "{'info': 'iat_data_5', 'iat': 1773060987}"],
  ['iat_data_8', 'false', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpbmZvIjoiaWF0X2RhdGFfOCIsImlhdCI6MTc3MzA2MDk4N30.t_zdsf4LabqAtH9BVGRLeMpGl3SMugZ63r31bucUs_o', "{'info': 'iat_data_8', 'iat': 1773060987}"],
  ['iat_data_1', 'true', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpbmZvIjoiaWF0X2RhdGFfMSIsImlhdCI6MTc3MzA2MDk4N30.dgNXL2PPjM-V5uiZ-9UxJB-uLwdTkbCvLhaOdOdiEZ8', "{'info': 'iat_data_1', 'iat': 1773060987}"],
  ['iat_data_19', 'true', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpbmZvIjoiaWF0X2RhdGFfMTkiLCJpYXQiOjE3NzMwNjA5ODd9.uZbB1CAHr3fWPUNDPOMC750LBmPnjSmv_BpxQcjKdOo', "{'info': 'iat_data_19', 'iat': 1773060987}"],
];

let failures = 0;
for (const [data, verifyIat, expectedToken, expectedRepr] of EXPECTED) {
  const payload = new Map([
    ['info', data],
    ['iat', 1773060987],
  ]);
  const token = jwt.encode(payload, 'secret');
  const decoded = jwt.decode(token, 'secret', {
    options: { verify_iat: verifyIat === 'true' },
    algorithms: ['HS256'],
  });
  const rendered = repr(decoded);

  const tokenOk = token === expectedToken;
  const reprOk = rendered === expectedRepr;
  if (!tokenOk || !reprOk) {
    failures++;
    console.log(`FAIL ${data}`);
    if (!tokenOk) console.log(`  token\n    want ${expectedToken}\n    got  ${token}`);
    if (!reprOk) console.log(`  repr\n    want ${expectedRepr}\n    got  ${rendered}`);
  } else {
    console.log(`ok   ${data} -> token + repr match ground truth`);
  }
}

console.log(`\n${EXPECTED.length - failures}/${EXPECTED.length} ground-truth samples matched`);
if (failures) process.exitCode = 1;

