 * @param {string} algorithm
 * @param {Map<string, unknown>|Record<string, unknown>|null} [additionalHeaders]
 * @returns {string} base64url segment
 */
function encodeHeader(algorithm, additionalHeaders) {
  const header = new Map([
    ['typ', 'JWT'],
    ['alg', algorithm],
  ]);
  if (additionalHeaders) {
    const entries =
      additionalHeaders instanceof Map
        ? additionalHeaders.entries()
        : Object.entries(additionalHeaders);
    for (const [key, value] of entries) header.set(key, value);
  }
