    this.hashAlgorithm = SHA256;
  }

  /**
   * @param {Uint8Array} message
   * @returns {Uint8Array} raw MAC bytes
   */
  sign(message) {
    return hmac(this.hashAlgorithm, this.key, message);
  }

  /**
   * @param {Uint8Array} message
   * @param {Uint8Array} signature
   * @returns {boolean}
