    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63] + '=';
  }
  return out;
}

/**
 * Encode bytes as base64url with the trailing `=` padding stripped, which is
 * the form JOSE uses for every segment of a compact serialization.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function base64urlEncode(bytes) {
  let out = '';
  let i = 0;
  for (; i + 2 < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out +=
      URL_ALPHABET[(n >> 18) & 63] +
      URL_ALPHABET[(n >> 12) & 63] +
      URL_ALPHABET[(n >> 6) & 63] +
      URL_ALPHABET[n & 63];
  }
  const rest = bytes.length - i;
  if (rest === 1) {
    const n = bytes[i] << 16;
    out += URL_ALPHABET[(n >> 18) & 63] + URL_ALPHABET[(n >> 12) & 63];
  } else if (rest === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
    out += URL_ALPHABET[(n >> 18) & 63] + URL_ALPHABET[(n >> 12) & 63] + URL_ALPHABET[(n >> 6) & 63];
  }
  return out;
}

/**
 * Decode base64url (padding optional).  Standard `+/` characters are accepted
 * too, matching the leniency of Python's `base64.urlsafe_b64decode` once the
 * padding has been restored.
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function base64urlDecode(text) {
  const clean = String(text).replace(/=+$/, '');
  const out = [];
  let buffer = 0;
  let bits = 0;
  for (let i = 0; i < clean.length; i++) {
    const code = clean.charCodeAt(i);
    let value = code < 256 ? URL_LOOKUP[code] : -1;
    if (value < 0 && code < 256) value = STD_LOOKUP[code];
    if (value < 0) throw new Error('Invalid base64url character');
    buffer = (buffer << 6) | value;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out.push((buffer >> bits) & 0xff);
    }
  }
  return Uint8Array.from(out);
}
